import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define REG_TILE_H 2
#define REG_TILE_W 2
#define COUT_TILE 4
__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int Cin, int H, int W,
    int Cout, int K, int stride, int pad,
    int Hout, int Wout,
    int TILE_H, int TILE_W,
    int SH, int SW,
    int numCoGroups)
{
    extern __shared__ float smem[];
    int tile_w_idx = blockIdx.x;
    int tile_h_idx = blockIdx.y;
    int nc = blockIdx.z;
    int co_group = nc % numCoGroups;
    int n = nc / numCoGroups;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tz = threadIdx.z;
    int co = co_group * COUT_TILE + tz;
    int h_start = tile_h_idx * TILE_H * stride - pad;
    int w_start = tile_w_idx * TILE_W * stride - pad;
    int blockThreadsX = blockDim.x;
    int blockThreadsY = blockDim.y;
    int blockThreadsZ = blockDim.z;
    int tid = (tz * blockThreadsY + ty) * blockThreadsX + tx;
    int nThreads = blockThreadsX * blockThreadsY * blockThreadsZ;
    int total_elems = Cin * SH * SW;
    for (int idx = tid; idx < total_elems; idx += nThreads) {
        int sw = idx % SW;
        int tmp = idx / SW;
        int sh = tmp % SH;
        int ci = tmp / SH;
        int h = h_start + sh;
        int w = w_start + sw;
        float val = 0.0f;
        if (h >= 0 && h < H && w >= 0 && w < W) {
            val = input[((n * Cin + ci) * H + h) * W + w];
        }
        smem[idx] = val;
    }
    __syncthreads();
    bool valid_co = (co < Cout);
    float sum[REG_TILE_H][REG_TILE_W];
    #pragma unroll
    for (int rh = 0; rh < REG_TILE_H; ++rh) {
        #pragma unroll
        for (int rw = 0; rw < REG_TILE_W; ++rw) {
            sum[rh][rw] = valid_co ? bias[co] : 0.0f;
        }
    }
    int base_local_h = ty * REG_TILE_H * stride;
    int base_local_w = tx * REG_TILE_W * stride;
    if (valid_co) {
        for (int ci = 0; ci < Cin; ++ci) {
            const float* weight_ptr = weight + ((co * Cin + ci) * K) * K;
            const float* smem_ci = smem + ci * SH * SW;
            for (int kh = 0; kh < K; ++kh) {
                const float* weight_row = weight_ptr + kh * K;
                #pragma unroll
                for (int rh = 0; rh < REG_TILE_H; ++rh) {
                    const float* smem_row = smem_ci + (base_local_h + rh * stride + kh) * SW;
                    for (int kw = 0; kw < K; ++kw) {
                        float wv = weight_row[kw];
                        #pragma unroll
                        for (int rw = 0; rw < REG_TILE_W; ++rw) {
                            sum[rh][rw] += smem_row[base_local_w + rw * stride + kw] * wv;
                        }
                    }
                }
            }
        }
    }
    if (valid_co) {
        #pragma unroll
        for (int rh = 0; rh < REG_TILE_H; ++rh) {
            int ho = tile_h_idx * TILE_H + ty * REG_TILE_H + rh;
            if (ho >= Hout) continue;
            #pragma unroll
            for (int rw = 0; rw < REG_TILE_W; ++rw) {
                int wo = tile_w_idx * TILE_W + tx * REG_TILE_W + rw;
                if (wo >= Wout) continue;
                output[((n * Cout + co) * Hout + ho) * Wout + wo] = sum[rh][rw];
            }
        }
    }
}
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad)
{
    input = input.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();
    int N = input.size(0);
    int Cin = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int Cout = weight.size(0);
    int K = weight.size(2);
    int Hout = (H + 2 * pad - K) / stride + 1;
    int Wout = (W + 2 * pad - K) / stride + 1;
    auto output = torch::empty({N, Cout, Hout, Wout}, input.options());
    const int TILE_H = 16;
    const int TILE_W = 16;
    const int REG_H = 2;
    const int REG_W = 2;
    int SH = (TILE_H - 1) * stride + K;
    int SW = (TILE_W - 1) * stride + K;
    int numCoGroups = (Cout + COUT_TILE - 1) / COUT_TILE;
    dim3 block(TILE_W / REG_W, TILE_H / REG_H, COUT_TILE);
    dim3 grid(
        (Wout + TILE_W - 1) / TILE_W,
        (Hout + TILE_H - 1) / TILE_H,
        N * numCoGroups
    );
    size_t smem_size = (size_t)Cin * SH * SW * sizeof(float);
    cudaError_t attr_err = cudaFuncSetAttribute(
        conv2d_forward_kernel,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem_size);
    TORCH_CHECK(attr_err == cudaSuccess,
        "Failed to set dynamic shared memory size: ", cudaGetErrorString(attr_err));
    conv2d_forward_kernel<<<grid, block, smem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, Cin, H, W,
        Cout, K, stride, pad,
        Hout, Wout,
        TILE_H, TILE_W,
        SH, SW,
        numCoGroups
    );
    cudaError_t launch_err = cudaGetLastError();
    TORCH_CHECK(launch_err == cudaSuccess,
        "conv2d_forward_kernel launch failed: ", cudaGetErrorString(launch_err));
    return output;
}
"""

conv2d_header = r"""
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_header,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels, self.kernel_size, self.kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        # Initialize similar to nn.Conv2d default init
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()
        bias = self.bias.cuda().contiguous()
        return conv2d_module.conv2d_forward_cuda(
            x, weight, bias, self.stride, self.padding
        )


def get_inputs():
    batch_size = 256
    return [torch.rand(batch_size, 3, 224, 224)]


def get_init_inputs():
    num_classes = 1000
    return [num_classes]

